--- a/src/vfx/waterRibbon.ts
+++ b/src/vfx/waterRibbon.ts
@@ -212,6 +212,14 @@ export const WATER05: boolean = q05('water05') || FARW05 || FLOWMAP05;
 export const MATCH05: boolean = q05('match05');
 export const on05 = (key: string): boolean => q05(key) || MATCH05;
 export const PROJ05: boolean = on05('proj05');
+/**
+ * `?proj05=1&projfar05=1` (2026-11-16 late, tools/proj05/bake.py … far): FAR-RIVER FIX. The exact layer E and the far
+ * block's layer F are baked a second time (assets/textures/water05/far1/) so that the far river also carries the approved
+ * pixels where the approved picture shows bank foam / wall on top of the game's river (there the first bake had no data:
+ * torn filler and the procedural far river showed at the far bend). Nothing else changes; without the switch the
+ * first bake is used as before.
+ */
+export const PROJFAR05: boolean = PROJ05 && on05('projfar05');
 /** `?proj05=1`: texture loads of other proj05 parts (far block, bank strip) that the game waits for before `ready` */
 export const proj05Pending: Promise<unknown>[] = [];

@@ -1650,14 +1658,14 @@ export function proj05Far() {
     uPjPost: { value: new THREE.Vector4(0.86, 1.36, 1.15, 0.18) }, uPjRes: { value: new THREE.Vector2(864, 1536) },
   };
   proj05Pending.push(new Promise<void>((res) => {
-    const tex = new THREE.TextureLoader().load(new URL('../../assets/textures/water05/proj05_F.png', import.meta.url).href, (t) => {
+    const tex = new THREE.TextureLoader().load(PROJFAR05 ? new URL('../../assets/textures/water05/far1/proj05_F.png', import.meta.url).href : new URL('../../assets/textures/water05/proj05_F.png', import.meta.url).href, (t) => {
       t.flipY = false; t.colorSpace = THREE.NoColorSpace; t.generateMipmaps = false; t.minFilter = THREE.LinearFilter; t.needsUpdate = true;
       res();
     }, undefined, () => res());
     tex.flipY = false;
     u.uPjF.value = tex;
   }));
-  proj05Pending.push(fetch(new URL('../../assets/textures/water05/proj05_lut.json', import.meta.url).href).then((r) => r.json()).then((l) => { u.uPjFZ.value = l.F.zmax; }).catch(() => {}));
+  proj05Pending.push(fetch(PROJFAR05 ? new URL('../../assets/textures/water05/far1/proj05_lut.json', import.meta.url).href : new URL('../../assets/textures/water05/proj05_lut.json', import.meta.url).href).then((r) => r.json()).then((l) => { u.uPjFZ.value = l.F.zmax; }).catch(() => {}));
   const size = new THREE.Vector2();
   const onBeforeRender = (renderer: THREE.WebGLRenderer) => {
     const rt = renderer.getRenderTarget();
@@ -1675,11 +1683,11 @@ function attachProj05(u: Record<string, THREE.IUniform>) {
   const qs = typeof location !== 'undefined' ? new URLSearchParams(location.search) : new URLSearchParams();
   const qn = (k: string, d: number) => { const v = qs.get(k); return v !== null && v !== '' && isFinite(+v) ? +v : d; };
   const urls = {
-    E: new URL('../../assets/textures/water05/proj05_E.png', import.meta.url).href,
+    E: PROJFAR05 ? new URL('../../assets/textures/water05/far1/proj05_E.png', import.meta.url).href : new URL('../../assets/textures/water05/proj05_E.png', import.meta.url).href,
     N: new URL('../../assets/textures/water05/proj05_N.png', import.meta.url).href,
     T: new URL('../../assets/textures/water05/proj05_T.png', import.meta.url).href,
     D: new URL('../../assets/textures/water05/proj05_D.png', import.meta.url).href,
-    lut: new URL('../../assets/textures/water05/proj05_lut.json', import.meta.url).href,
+    lut: PROJFAR05 ? new URL('../../assets/textures/water05/far1/proj05_lut.json', import.meta.url).href : new URL('../../assets/textures/water05/proj05_lut.json', import.meta.url).href,
   };
   const empty = new THREE.DataTexture(new Uint8Array([0, 0, 0, 0]), 1, 1);
   empty.needsUpdate = true;
@@ -1697,7 +1705,7 @@ function attachProj05(u: Record<string, THREE.IUniform>) {
   // still, and `projflowmix05` (share of the picture that travels; default 0.5, 1 = all) keeps the rest of the approved
   // picture fixed where it is painted — measured (qa/pilot05/proj/flow2/NOTES.md): similarity to the unflowed design
   // over a cycle 0.72 (old flow) -> 0.93, never below 0.90; direction toward the camera in every tracked frame pair.
-  const FLOW2 = qs.get('projflow05') === '2';
+  const FLOW2 = qs.get('projflow05') === '2' || (MATCH05 && qs.get('projflow05') === null);   // master switch: streamline flow
   u.uPjFlow = { value: new THREE.Vector4(qn('projflowd05', 1.6), rate, 0.5 - ((12 * rate) % 1), qs.get('projflow05') === '0' ? 0 : 1) };
   u.uPjWN = { value: empty }; u.uPjWT = { value: empty };
   u.uPjFlow2 = { value: new THREE.Vector4(0, 2, 4.8, THREE.MathUtils.clamp(qn('projflowmix05', 0.5), 0, 1)) };
@@ -1711,7 +1719,7 @@ function attachProj05(u: Record<string, THREE.IUniform>) {
   // (pixel-identical locked picture). `projneardetail05` = share of the fine-streak detail layer kept on T2: default 1
   // (measured on ride frames at 8 / 17 / 35 u: 0 left the stretch where the tile's source is soft — 8 u — softer than
   // before; 1 is sharper than before in every band and showed no grain; 0 and 0.5 stay available for comparison).
-  const NEAR = qs.get('projnear05') === '1';
+  const NEAR = on05('projnear05');
   u.uPjNear = { value: new THREE.Vector4(0, THREE.MathUtils.clamp(qn('projneardetail05', 1), 0, 1), 0, 0) };
   u.uPjT2 = { value: empty }; u.uPjWT2 = { value: empty };
   u.uPjT2S = { value: new THREE.Vector2(0, 1) };
diff --git a/tools/proj05/bake.py b/tools/proj05/bake.py
index 66c7ca8..a566f0a 100644
--- a/tools/proj05/bake.py
+++ b/tools/proj05/bake.py
@@ -19,6 +19,13 @@ from PIL import Image
 from scipy.ndimage import gaussian_filter, gaussian_filter1d, binary_dilation, binary_erosion

 probe, tdir, out = sys.argv[1], sys.argv[2], sys.argv[3]
+# optional 4th argument "far" (`&projfar05=1`, 2026-11-16 late): FAR-RIVER FIX. Where the game's far river (ribbon beyond
+# S_FAR0 and the forced-perspective far block) is on screen but the approved picture shows something else there (bank
+# foam, wall), the old bake had no data and the game showed filler / the procedural far river (torn "flag" at the far
+# bend). With "far" those texels take the APPROVED pixels as they are, so the locked view shows the approved picture on
+# the whole far river. Only E, F and the LUT differ (out dir: assets/textures/water05/far1/).
+FARFIX = len(sys.argv) > 4 and sys.argv[4] == "far"
+S_FAR0 = 157.0
 os.makedirs(out, exist_ok=True)
 W, H = 864, 1536
 R = np.fromfile(os.path.join(probe, "uv_river.f32"), np.float32).reshape(H, W, 4).astype(np.float64)
@@ -27,12 +34,20 @@ wm = np.asarray(Image.open(os.path.join(tdir, "water_mask.png"))) > 127
 # coins are filled in the target from the user's artwork (make_target.py); the along-s hole filling below stays for gaps
 coin = np.zeros((H, W), bool)
 tgt = np.asarray(Image.open(os.path.join(tdir, "target_05.png")).convert("RGB"), np.float64) / 255
+if FARFIX:      # outside the approved water footprint the target IS the approved picture
+    here = os.path.dirname(os.path.abspath(__file__))
+    appr = np.asarray(Image.open(os.path.join(here, "..", "..", "references", "05_flow_into_the_current.png")).convert("RGB"), np.float64) / 255
+    tgt = np.where(wm[..., None], tgt, appr)
 # colour feedback from the live capture (tools/proj05/residual.py): what the bloom pass adds is taken out of the bake
 if os.path.exists(os.path.join(tdir, "correction.npz")):
     tgt = np.clip(tgt - np.load(os.path.join(tdir, "correction.npz"))["c"].astype(np.float64), 0, 1)
 U, S = R[..., 0], R[..., 1]
 S_CUT = 182.0                                   # the real ribbon ends behind the far block's seam
 use = surf & wm & (S < S_CUT)
+use_all = use
+if FARFIX:      # E only: the far ribbon also where the approved picture shows no water (N / T / D keep the water-only set)
+    useE = surf & (S < S_CUT) & (wm | (S > S_FAR0))
+    use = useE
 ys, xs = np.nonzero(use)
 su, ss, sc, scoin = U[use], S[use], tgt[use], coin[use]
 # locked-view density along s (screen rows per unit s), per pixel
@@ -127,7 +142,25 @@ holeE, _ = splat(xE, yE, scoin[:, None].astype(float), WE, NE)
 wtE, _ = splat(xE, yE, (~scoin)[:, None].astype(float), WE, NE)
 E, validE = finish(accE, wtE[..., 0], holeE[..., 0], max_gap=int(NE * 0.35))
 alphaE = gaussian_filter(binary_erosion(validE, iterations=1).astype(float), 0.8)
+if FARFIX:
+    # water the locked eye never saw (behind wave crests, long interpolated runs along s): the straight interpolation
+    # shows as a flat blank patch as soon as Benny rides forward. Those texels are released (alpha 0) so the tile
+    # layers — the approved design, repeating — show there instead. Runs of <= UNSEEN_MIN rows stay (sub-texel gaps).
+    UNSEEN_MIN = 8
+    fl = finish.filled.copy()
+    run = np.zeros(fl.shape, np.int32)
+    for y in range(fl.shape[0]):                       # run length ending at y (down each column)
+        run[y] = np.where(fl[y], (run[y - 1] if y else 0) + 1, 0)
+    for y in range(fl.shape[0] - 2, -1, -1):           # spread the full run length back up the run
+        run[y] = np.where(fl[y] & fl[y + 1], np.maximum(run[y], run[y + 1]), run[y])
+    unseen = binary_erosion(run > UNSEEN_MIN, iterations=2)
+    alphaE = alphaE * (1.0 - np.clip(gaussian_filter(unseen.astype(float), 1.0) * 1.6, 0, 1))
+    print(json.dumps(dict(E_unseen_texels=int(unseen.sum()), E_texels=int(unseen.size))))

+if FARFIX:      # N / T / D: water-only samples, as before
+    use = use_all
+    ys, xs = np.nonzero(use)
+    su, ss, sc, scoin = U[use], S[use], tgt[use], coin[use]
 # ---------------------------------------------------------------- N (near, full width) layer
 sN0, sN1, dN, WN = 126.0, 166.0, 24, 512
 NN = int((sN1 - sN0) * dN)
@@ -201,7 +234,7 @@ D = np.clip(0.5 + hpw * 1.0, 0, 1)

 # ---------------------------------------------------------------- F (far river block) layer
 # the forced-perspective far river (far05.ts): its own coordinates (uv.x across the floor chord, virtual depth Z)
-farm = (np.abs(R[..., 2] - 3) < 0.01) & wm
+farm = (np.abs(R[..., 2] - 3) < 0.01) & (wm | FARFIX)
 fx_, fz_ = R[..., 0][farm], R[..., 1][farm]
 fcol, fcoin = tgt[farm], coin[farm]
 ZMAX = float(max(fz_.max(), 1.0)) if farm.any() else 400.0
