  vec3 mu = uPjVP.yzw;
  vec3 vp = clamp(mu + ((1.0 - w) * (a - mu) + w * (b - mu)) * inversesqrt(max(w * w + (1.0 - w) * (1.0 - w), 0.5)), 0.0, 1.0);
  return mix(lin, vp, k);
}

